8: class MemoryReader
9: {
10: public:
11:     MemoryReader(HANDLE processHandle);
12:     ~MemoryReader();
13: 
14:     template<typename T>
15:     T Read(uintptr_t address) const
16:     {
17:         T buffer = {};
18:         if (address == 0)
19:             return buffer;
20:         ReadProcessMemory(m_processHandle, (LPCVOID)address, &buffer, sizeof(T), nullptr);
21:         return buffer;
22:     }
23: 
24:     template<typename T>
25:     bool Write(uintptr_t address, const T& value) const
26:     {
27:         if (address == 0)
28:             return false;
29:         return WriteProcessMemory(m_processHandle, (LPVOID)address, (LPCVOID)&value, sizeof(T), nullptr);
30:     }
31: 
32:     /**
33:      * Find byte pattern in process memory
34:      * @param pattern Byte pattern to search (can be NULL bytes)
35:      * @param mask    Mask string: 'x' = must match, '?' = wildcard
36:      * @param startAddress Base address to search from
37:      * @param searchSize   Number of bytes to search
38:      * @return Address of pattern or 0 if not found
39:      */
40:     uintptr_t FindPattern(const char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const;
41: 
42:     /**
43:      * Find pattern using unsigned char array
44:      */
45:     uintptr_t FindPatternEx(const unsigned char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const;
46: 
47:     /**
48:      * Find pattern in specific memory region
49:      */
50:     uintptr_t FindPatternRegion(const char* pattern, const char* mask, const MEMORY_BASIC_INFORMATION& region) const;
51: 
52:     /**
53:      * Read null-terminated string
54:      */
55:     std::string ReadString(uintptr_t address, size_t maxLength = 256) const
56:     {
57:         std::string result;
58:         if (address == 0)
59:             return result;
60:         
61:         char buffer[256];
62:         size_t toRead = maxLength < sizeof(buffer) - 1 ? maxLength : sizeof(buffer) - 1;
63:         ReadProcessMemory(m_processHandle, (LPCVOID)address, buffer, toRead, nullptr);
64:         buffer[toRead] = '\0';
65:         result = buffer;
66:         return result;
67:     }
68: 
69: private:
70:     HANDLE m_processHandle;
71: };

