48: {
49:     if (!m_processHandle)
50:         return 0;
51: 
52:     size_t patternLength = strlen(mask);
53:     if (patternLength == 0 || searchSize < patternLength)
54:         return 0;
55: 
56:     std::unique_ptr<unsigned char[]> buffer(new unsigned char[searchSize]);
57: 
58:     if (!ReadProcessMemory(m_processHandle, (LPCVOID)startAddress, buffer.get(), searchSize, nullptr))
59:         return 0;
60: 
61:     for (size_t i = 0; i <= searchSize - patternLength; i++)
62:     {
63:         bool match = true;
64:         for (size_t j = 0; j < patternLength; j++)
65:         {
66:             if (mask[j] == 'x' && buffer[i + j] != pattern[j])
67:             {
68:                 match = false;
69:                 break;
70:             }
71:         }
72: 
73:         if (match)
74:             return startAddress + i;
75:     }
76: 
77:     return 0;
78: }
