80: uintptr_t MemoryReader::FindPatternRegion(const char* pattern, const char* mask, const MEMORY_BASIC_INFORMATION& region) const
81: {
82:     if (!m_processHandle || region.AllocationBase == nullptr)
83:         return 0;
84: 
85:     return FindPattern(pattern, mask, (uintptr_t)region.BaseAddress, region.RegionSize);
86: }
