22: MemoryHookTestResult MemoryHookTest::TestPatternScanning(HANDLE processHandle, DWORD processId)
23: {
24:     MemoryHookTestResult result;
25:     result.testName = "Pattern Scanning";
26:     result.success = false;
27:     
28:     try
29:     {
30:         MemoryReader reader(processHandle);
31:         
32:         // Get D2R module base
33:         MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
34:         HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, processId);
35:         
36:         if (hModuleSnap == INVALID_HANDLE_VALUE)
37:         {
38:             result.message = "Failed to create module snapshot";
39:             return result;
40:         }
41:         
42:         uintptr_t moduleBase = 0;
43:         if (Module32First(hModuleSnap, &me32))
44:         {
45:             do
46:             {
47:                 if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
48:                 {
49:                     moduleBase = (uintptr_t)me32.modBaseAddr;
50:                     break;
51:                 }
52:             } while (Module32Next(hModuleSnap, &me32));
53:         }
54:         CloseHandle(hModuleSnap);
55:         
56:         if (!moduleBase)
57:         {
58:             result.message = "D2R.exe module not found in target process";
59:             return result;
60:         }
61:         
62:         // Test player position pattern
63:         const unsigned char playerPosPattern[] = {
64:             0xF3, 0x0F, 0x10, 0x87, 0x00, 0x00, 0x00, 0x00};
65:         const char *playerMask = "xxxx????";
66:         
67:         uintptr_t playerPatternFound = reader.FindPatternEx(
68:             playerPosPattern,
69:             playerMask,
70:             moduleBase,
71:             GameOffsets::PATTERN_SEARCH_SIZE);
72:         
73:         // Test mob list pattern
74:         const unsigned char mobListPattern[] = {
75:             0x48, 0x8B, 0x41, 0x30};
76:         const char *mobMask = "xxxx";
77:         
78:         uintptr_t mobPatternFound = reader.FindPatternEx(
79:             mobListPattern,
80:             mobMask,
81:             moduleBase,
82:             GameOffsets::PATTERN_SEARCH_SIZE);
83:         
84:         std::stringstream ss;
85:         ss << "Player pattern: ";
86:         if (playerPatternFound)
87:         {
88:             ss << "FOUND at 0x" << std::hex << playerPatternFound << " | ";
89:         }
90:         else
91:         {
92:             ss << "NOT FOUND | ";
93:         }
94:         
95:         ss << "Mob pattern: ";
96:         if (mobPatternFound)
97:         {
98:             ss << "FOUND at 0x" << std::hex << mobPatternFound;
99:         }
100:         else
101:         {
102:             ss << "NOT FOUND";
103:         }
104:         
105:         result.message = ss.str();
106:         result.success = (playerPatternFound != 0) && (mobPatternFound != 0);
107:     }
108:     catch (const std::exception &e)
109:     {
110:         result.message = std::string("Exception: ") + e.what();
111:     }
112:     catch (...)
113:     {
114:         result.message = "Unknown exception during pattern scanning";
115:     }
116:     
117:     return result;
118: }
