378: MemoryHookTestResult MemoryHookTest::TestMemoryReadAccuracy(HANDLE processHandle, DWORD processId)
379: {
380:     MemoryHookTestResult result;
381:     result.testName = "Memory Read Accuracy";
382:     result.success = false;
383:     
384:     try
385:     {
386:         MemoryReader reader(processHandle);
387:         
388:         MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
389:         HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, processId);
390:         
391:         if (hModuleSnap == INVALID_HANDLE_VALUE)
392:         {
393:             result.message = "Failed to create module snapshot";
394:             return result;
395:         }
396:         
397:         uintptr_t moduleBase = 0;
398:         if (Module32First(hModuleSnap, &me32))
399:         {
400:             do
401:             {
402:                 if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
403:                 {
404:                     moduleBase = (uintptr_t)me32.modBaseAddr;
405:                     break;
406:                 }
407:             } while (Module32Next(hModuleSnap, &me32));
408:         }
409:         CloseHandle(hModuleSnap);
410:         
411:         if (!moduleBase)
412:         {
413:             result.message = "D2R.exe module not found";
414:             return result;
415:         }
416:         
417:         // Read same value multiple times to check consistency - try multiple patterns
418:         uintptr_t found = 0;
419:         
420:         const unsigned char p1[] = {0xF3, 0x0F, 0x10, 0x87, 0x00, 0x00, 0x00, 0x00};
421:         found = reader.FindPatternEx(p1, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
422:         
423:         if (!found)
424:         {
425:             const unsigned char p2[] = {0xF3, 0x0F, 0x10, 0x83, 0x00, 0x00, 0x00, 0x00};
426:             found = reader.FindPatternEx(p2, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
427:         }
428:         
429:         if (!found)
430:         {
431:             const unsigned char p3[] = {0xF3, 0x0F, 0x10, 0x8F, 0x00, 0x00, 0x00, 0x00};
432:             found = reader.FindPatternEx(p3, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
433:         }
434:         
435:         if (!found)
436:         {
437:             const unsigned char p4[] = {0xF3, 0x0F, 0x10, 0x8B, 0x00, 0x00, 0x00, 0x00};
438:             found = reader.FindPatternEx(p4, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
439:         }
440:         
441:         if (!found)
442:         {
443:             result.message = "Pattern not found";
444:             return result;
445:         }
446:         
447:         // Extract offset from instruction (at found+4, 4 bytes)
448:         int32_t positionOffset = reader.Read<int32_t>(found + 4);
449:         uintptr_t playerBase = found - positionOffset;
450:         
451:         // Read 3 times and check for consistency
452:         float pos1X = reader.Read<float>(playerBase + positionOffset);
453:         Sleep(10);
454:         float pos2X = reader.Read<float>(playerBase + positionOffset);
455:         Sleep(10);
456:         float pos3X = reader.Read<float>(playerBase + positionOffset);
457:         
458:         // Values should be identical or very close (within reasonable tolerance)
459:         float diff12 = fabs(pos1X - pos2X);
460:         float diff23 = fabs(pos2X - pos3X);
461:         
462:         result.playerX = pos1X;
463:         
464:         std::stringstream ss;
465:         ss << "Consecutive reads: " << std::fixed << std::setprecision(4)
466:            << pos1X << " -> " << pos2X << " -> " << pos3X << " | "
467:            << "Diff: " << diff12 << ", " << diff23;
468:         
469:         // Allow up to 10 units difference (player might be moving)
470:         if (diff12 < 50.0f && diff23 < 50.0f)
471:         {
472:             result.success = true;
