13: uintptr_t MemoryReader::FindPattern(const char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const
14: {
15:     if (!m_processHandle)
16:         return 0;
17: 
18:     size_t patternLength = strlen(mask);
19:     if (patternLength == 0 || searchSize < patternLength)
20:         return 0;
21: 
22:     std::unique_ptr<unsigned char[]> buffer(new unsigned char[searchSize]);
23: 
24:     if (!ReadProcessMemory(m_processHandle, (LPCVOID)startAddress, buffer.get(), searchSize, nullptr))
25:         return 0;
26: 
27:     for (size_t i = 0; i <= searchSize - patternLength; i++)
28:     {
29:         bool match = true;
30:         for (size_t j = 0; j < patternLength; j++)
31:         {
32:             // 'x' = must match, '?' = wildcard (any byte)
33:             if (mask[j] == 'x' && buffer[i + j] != (unsigned char)pattern[j])
34:             {
35:                 match = false;
36:                 break;
37:             }
38:         }
39: 
40:         if (match)
41:             return startAddress + i;
42:     }
43: 
44:     return 0;
45: }
