// This is dangerous but better than completely blind clicking
printf("\n[!] ALL PATTERNS FAILED - Attempting last-resort static fallback...\n");

// Try to read player level/class to infer structure location
// If we can read valid level, we can calculate structure base
try
{
    MemoryReader reader(m_processHandle);
    MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
    HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);

    if (hModuleSnap != INVALID_HANDLE_VALUE && Module32First(hModuleSnap, &me32))
    {
        uintptr_t moduleBase = 0;
        do {
            if (_wcsicmp(me32.szModule, L"D2R.exe") == 0) {
                moduleBase = (uintptr_t)me32.modBaseAddr;
                break;
            }
        } while (Module32Next(hModuleSnap, &me32));
        CloseHandle(hModuleSnap);

        if (moduleBase)
        {
            // Try common data segment offsets where player structure might be
            // D2R typically stores player data at relatively fixed offsets in .data section
            const uintptr_t commonOffsets[] = {
                0x200000, 0x250000, 0x300000, 0x350000, 0x400000,
                0x1500000, 0x1600000, 0x1700000, 0x1800000
            };

            for (uintptr_t offset : commonOffsets)
            {
                uintptr_t testBase = moduleBase + offset;
                int testLevel = reader.Read<int>(testBase + GameOffsets::Player::LEVEL);
                int testClass = reader.Read<int>(testBase + GameOffsets::Player::CLASS_TYPE);

                // Validate if these look like real values
                if (testLevel > 0 && testLevel <= 99 && testClass >= 0 && testClass < 6)
                {
                    printf("[+] Found valid player structure at offset 0x%llX!\n", offset);
                    printf("[+] Level: %d, Class: %d\n", testLevel, testClass);

                    // Try to read position from this base
                    float posX = reader.Read<float>(testBase + GameOffsets::Player::POSITION_X);
                    float posY = reader.Read<float>(testBase + GameOffsets::Player::POSITION_Y);

                    if (std::isfinite(posX) && std::isfinite(posY) && 
                        posX > 0 && posY > 0 && posX < 10000 && posY < 10000)
                    {
                        state.position.x = posX;
                        state.position.y = posY;
                        state.classType = testClass;
                        state.level = testLevel;
                        state.experience = reader.Read<int>(testBase + GameOffsets::Player::EXPERIENCE);

                        printf("[+] SUCCESS! Using discovered player structure at 0x%llX\n", testBase);
                        printf("[+] Position: (%.2f, %.2f)\n", posX, posY);
                        return state;
                    }
                }
            }

            printf("[!] Static offsets search failed too.\n");
        }
    }
}
